--!strict
local Players = game:GetService("Players");
local ReplicatedStorage = game:GetService("ReplicatedStorage");
local AdminRemote = ReplicatedStorage:WaitForChild("Remotes"):WaitForChild("AdminRemote") :: RemoteEvent;

local AdminHandler = {};
local ADMIN_IDS = { [12345678] = true }; -- Replace with actual IDs

function AdminHandler.IsAdmin(userId: number): boolean
	return ADMIN_IDS[userId] == true
end

AdminRemote.OnServerEvent:Connect(function(player, commandName, args)
	if not AdminHandler.IsAdmin(player.UserId) then return end
	local Commands = require(script.Commands);
	if Commands[commandName] then
		Commands[commandName](player, args);
	end
end);

return AdminHandler

